import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"MiniMax Code glossary","description":"No procedures. Separate Code, Agent, Hailuo, and Talkie, then desktop, CLI, and the two mode axes.","frontmatter":{"title":"MiniMax Code glossary","description":"No procedures. Separate Code, Agent, Hailuo, and Talkie, then desktop, CLI, and the two mode axes.","domain":"product","tags":["coding-agent"],"role":"glossary"},"headers":[],"relativePath":"products/minimax-code/minimax-code-glossary.md","filePath":"products/minimax-code/minimax-code-glossary.md","lastUpdated":1787110548000}'),i={name:"products/minimax-code/minimax-code-glossary.md"};function n(d,e,s,l,c,m){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="minimax-code-glossary" tabindex="-1">MiniMax Code glossary <a class="header-anchor" href="#minimax-code-glossary" aria-label="Permalink to &quot;MiniMax Code glossary&quot;">​</a></h1><p>No procedures. These names collide. Pick a door on the <a href="./">learning map</a>.</p><h2 id="everything-named-minimax" tabindex="-1">Everything named MiniMax <a class="header-anchor" href="#everything-named-minimax" aria-label="Permalink to &quot;Everything named MiniMax&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>What it is</th><th>Where</th></tr></thead><tbody><tr><td><strong>MiniMax Code</strong></td><td>First-party coding agent. Desktop app + CLI <code>mcode</code></td><td><a href="https://agent.minimax.io/docs/code/welcome" target="_blank" rel="noreferrer">welcome</a>, <a href="https://agent.minimax.io/download" target="_blank" rel="noreferrer">download</a>, <a href="https://agent.minimax.io/docs/cli/quick-start" target="_blank" rel="noreferrer">CLI</a></td></tr><tr><td>MiniMax Agent</td><td>Web general agent. Desktop was renamed to Code; the web product is still Agent</td><td><a href="https://agent.minimax.io/" target="_blank" rel="noreferrer">agent.minimax.io</a>, site issue #73</td></tr><tr><td>MiniMax Design</td><td>Commercial content agent platform</td><td><a href="https://design.minimax.io/" target="_blank" rel="noreferrer">design.minimax.io</a></td></tr><tr><td>MiniMax Hub</td><td>Name still used on the CN About nav</td><td><a href="https://www.minimaxi.com/about" target="_blank" rel="noreferrer">about</a>. Same family as Design; no second tutorial</td></tr><tr><td>MiniMax Audio</td><td>Speech and music</td><td><a href="https://www.minimax.io/audio" target="_blank" rel="noreferrer">minimax.io/audio</a></td></tr><tr><td>Hailuo / MiniMax H3</td><td>Video brand and model</td><td><a href="https://hailuoai.video/" target="_blank" rel="noreferrer">hailuoai.video</a></td></tr><tr><td>Talkie</td><td>International character product on the Product nav</td><td><a href="https://www.minimax.io/" target="_blank" rel="noreferrer">minimax.io</a></td></tr><tr><td>星野 (Xingye)</td><td>CN character community</td><td><a href="https://www.xingyeai.com/" target="_blank" rel="noreferrer">xingyeai.com</a></td></tr><tr><td>MiniMax M3</td><td>Coding / agentic model, 1M context</td><td><a href="https://platform.minimax.io/docs/guides/models-intro" target="_blank" rel="noreferrer">models-intro</a></td></tr><tr><td>Token Plan</td><td>Open Platform subscription</td><td><a href="https://platform.minimax.io/" target="_blank" rel="noreferrer">platform</a></td></tr><tr><td>AI coding tools guide</td><td>Point M3 at Claude Code / Cursor</td><td><a href="https://platform.minimax.io/docs/guides/text-ai-coding-tools" target="_blank" rel="noreferrer">text-ai-coding-tools</a></td></tr></tbody></table><p><strong>Do not write as fact:</strong></p><ul><li>MiniMax Code is &quot;just the M3 API wrapper&quot;.</li><li>The CLI command is <code>minimax</code>. Official CLI command is <code>mcode</code>. Changelog v3.0.33&#39;s &quot;minimax CLI shortcut&quot; has no standalone flag page.</li><li>An official npm package name. None found on 2026-08-19.</li><li>GitHub <code>MiniMax-AI/Mini-Agent</code> is MiniMax Code.</li><li>An official VS Code plugin. Official editor integration is ACP plus a Zed example.</li></ul><h2 id="one-product-two-faces" tabindex="-1">One product, two faces <a class="header-anchor" href="#one-product-two-faces" aria-label="Permalink to &quot;One product, two faces&quot;">​</a></h2><p>Official: &quot;MiniMax Code CLI is the terminal entry for MiniMax Code developer workflows. It complements the desktop client.&quot;</p><table tabindex="0"><thead><tr><th>Face</th><th>Entry</th><th>Typical use</th></tr></thead><tbody><tr><td>Desktop</td><td>Downloadable installer</td><td>Graphical tasks, browser, schedules, Remote Control</td></tr><tr><td>CLI TUI</td><td><code>mcode</code></td><td>Humans editing a repo in a terminal</td></tr><tr><td>CLI Headless</td><td><code>mcode exec</code></td><td>CI and scripts</td></tr><tr><td>CLI ACP</td><td><code>mcode acp</code></td><td>Embed in an editor</td></tr></tbody></table><p>The CLI does <strong>not</strong> depend on desktop Electron / IPC. Do not assume Browser or Computer Use exist in the CLI.</p><h2 id="two-orthogonal-mode-axes" tabindex="-1">Two orthogonal mode axes <a class="header-anchor" href="#two-orthogonal-mode-axes" aria-label="Permalink to &quot;Two orthogonal mode axes&quot;">​</a></h2><p>Desktop <strong>Coding / Work</strong>: same agent, different tool exposure. Use Coding to change a repo.</p><p>CLI <strong>Plan Mode</strong>: plan the next message or act now. <code>Shift+Tab</code> / <code>/plan</code>.</p><p>CLI <strong>permission mode</strong>: whether tools ask you. <code>Alt+M</code> / <code>/permission</code> → Ask / Auto / Full access.</p><p><code>mcode exec --permission</code> uses <code>ask</code> / <code>smart</code> / <code>full</code> / <code>off</code>. That is not the same enum as the TUI labels.</p><h2 id="agent-team" tabindex="-1">Agent Team <a class="header-anchor" href="#agent-team" aria-label="Permalink to &quot;Agent Team&quot;">​</a></h2><p>Official: extra specialist agents appear when the task is complex. You describe the goal; the product splits, assigns, tracks, and summarizes.</p><p>This is a MiniMax Code capability, not a separate product, and not the web MiniMax Agent.</p><h2 id="workspace-skills-memory" tabindex="-1">Workspace, skills, memory <a class="header-anchor" href="#workspace-skills-memory" aria-label="Permalink to &quot;Workspace, skills, memory&quot;">​</a></h2><ul><li><strong>Workspace</strong>: a local project directory. The agent reads, runs commands, and reports changes there.</li><li><strong>Skills</strong>: reusable workflows. The first-task page says you can invoke them with <code>/</code>.</li><li><strong>Memory</strong>: preferences, project conventions, long-term patterns (standalone desktop docs page).</li><li><strong><code>AGENTS.md</code></strong>: project instructions that <code>mcode init</code> creates or updates.</li></ul><h2 id="accounts-and-quotas" tabindex="-1">Accounts and quotas <a class="header-anchor" href="#accounts-and-quotas" aria-label="Permalink to &quot;Accounts and quotas&quot;">​</a></h2><p>Sign in with a MiniMax account on the desktop or via <code>mcode login</code>. Your own MiniMax API key goes through in-product settings or <code>mcode provider</code>.</p><p>Token Plan is an Open Platform subscription. The M3 post says Code can use Token Plan. Do not treat desktop Plus / Max / Ultra list prices and Token Plan USD tiers as one price list. Usage page: follow the in-product display.</p>',23)])])}const x=t(i,[["render",n]]);export{f as __pageData,x as default};
